package com.acme.auth

import java.time.Clock
import java.util.concurrent.ConcurrentHashMap

/** Fixed one-minute window per key, kept in memory. */
class RateLimiter(private val limit: Int = 5, private val clock: Clock = Clock.systemUTC()) {
    private class Window(val minute: Long, var count: Int)
    private val windows = ConcurrentHashMap<String, Window>()

    /** Seconds to wait before retrying, or 0 when the call is allowed. */
    fun acquire(key: String): Long {
        val now = clock.millis()
        val w = windows.compute(key) { _, old ->
            if (old == null || old.minute != now / 60_000) Window(now / 60_000, 1) else old.apply { count++ }
        }!!
        return if (w.count <= limit) 0 else 60 - (now / 1000) % 60
    }
}

